// the linemap pass: draws the typeset lines into the lyrics texture the styles sample
static NSString *const kSGRLyricsLinemapSource = @LINEMAPSOURCE_BODY;

// the Poster style, a letterpress page the cover prints through
static NSString *const kSGRLyricsPosterSource = @POSTERSOURCE_BODY;

// the Cut style, words cut out of the cover's own colour
static NSString *const kSGRLyricsCutSource = @CUTSOURCE_BODY;

NSString *SGRLyricsBuiltinSource(NSInteger index) {
    static NSString *const sources[] = {kSGRLyricsLinemapSource, kSGRLyricsPosterSource, kSGRLyricsCutSource};
    return index >= 0 && index < 3 ? sources[index] : nil;
}
